def solve(A):
    A=np.array(A); H,W=A.shape
    B=A.copy()
    objs=[]  # (r,c,color)
    for r in range(H):
        for c in range(W):
            if A[r,c]==3 and 0<r<H-1 and 0<c<W-1:
                if A[r-1,c]==3 and A[r+1,c]==3 and A[r,c-1]==3 and A[r,c+1]==3:
                    objs.append((r,c,A[r,c]))
    # horizontal rays first: fill 0s, skip own arms, stop at other 3s
    for r,c,col in objs:
        for d in (-1,1):
            cc=c+d
            while 0<=cc<W:
                v=A[r,cc]
                if v==3:
                    if (r,cc) in [(r,c-1),(r,c+1)]: cc+=d; continue
                    break
                if v!=0: break
                B[r,cc]=col; cc+=d
    # 0-rays (empty pluses) erase: overwrite non-3 along full lines
    for r,c,col in objs:
        if col==0:
            for rr in range(H):
                if B[rr,c]!=3: B[rr,c]=0
            for cc in range(W):
                if B[r,cc]!=3: B[r,cc]=0
    # vertical colored rays: overwrite everything except 3s
    for r,c,col in objs:
        if col==0: continue
        for d in (-1,1):
            rr=r+d
            while 0<=rr<H:
                if A[rr,c]!=3: B[rr,c]=col
                rr+=d
    return B

